const char* getNamedResource (const char* resourceNameUTF8, int& numBytes);
const char* getNamedResource (const char* resourceNameUTF8, int& numBytes)
{
    unsigned int hash = 0;

    if (resourceNameUTF8 != nullptr)
        while (*resourceNameUTF8 != 0)
            hash = 31 * hash + (unsigned int) *resourceNameUTF8++;

    switch (hash)
    {
        case 0x8cd65f28:  numBytes = 33374; return Hat_wav;
        case 0xd0670593:  numBytes = 43994; return Kick_wav;
        case 0x6e6e972e:  numBytes = 2105090; return morning_png;
        case 0x88726fa6:  numBytes = 81728; return Snare_wav;
        default: break;
    }

    numBytes = 0;
    return nullptr;
}

